const makeSubscriptionProfile = (
  subject: CodexOAuthSubjectType,
  credentialRevision: string
) =>
  Schema.decodeUnknownEffect(CodexSubscriptionProfile)({
    profileVersion: 2,
    profileKind: "subscription",
    subject,
